  1	package com.pousadamarealta;
  2	
  3	import io.javalin.Javalin;
  4	import com.pousadamarealta.infrastructure.Database;
  5	import com.pousadamarealta.handler.RoomHandler;
  6	import com.pousadamarealta.handler.ReservationHandler;
  7	import com.pousadamarealta.handler.MessageHandler;
  8	import com.pousadamarealta.handler.ReportHandler;
  9	
 10	public class Application {
 11	    public static void main(String[] args) throws Exception {
 12	        Database db = new Database();
 13	        db.initialize();
 14	
 15	        RoomHandler roomHandler = new RoomHandler(db);
 16	        ReservationHandler reservationHandler = new ReservationHandler(db);
 17	        MessageHandler messageHandler = new MessageHandler(db);
 18	        ReportHandler reportHandler = new ReportHandler(db);
 19	
 20	        int port = Integer.parseInt(System.getenv().getOrDefault("PORT", "7070"));
 21	
 22	        Javalin app = Javalin.create()
 23	                .get("/rooms", roomHandler::listRooms)
 24	                .post("/reservations", reservationHandler::createReservation)
 25	                .get("/reservations/{id}", reservationHandler::getReservation)
 26	                .post("/reservations/{id}/confirmation", reservationHandler::confirmReservation)
 27	                .post("/reservations/{id}/cancellation", reservationHandler::cancelReservation)
 28	                .post("/reservations/{id}/check-in", reservationHandler::checkIn)
 29	                .post("/reservations/{id}/check-out", reservationHandler::checkOut)
 30	                .get("/reservations/{id}/document", reservationHandler::getDocument)
 31	                .get("/messages", messageHandler::listMessages)
 32	                .get("/reports/occupancy", reportHandler::occupancy)
 33	                .get("/reports/revenue", reportHandler::revenue)
 34	                .get("/reports/tourism-tax", reportHandler::tourismTax)
 35	                .get("/reports/rate-plans", reportHandler::ratePlans)
 36	                .start(port);
 37	
 38	        Runtime.getRuntime().addShutdownHook(new Thread(app::stop));
 39	    }
 40	}
 41	package com.pousadamarealta.handler;
 42	
 43	import io.javalin.http.Context;
 44	import com.pousadamarealta.infrastructure.Database;
 45	import com.pousadamarealta.service.ReservationService;
 46	import com.pousadamarealta.service.ValidationException;
 47	import com.pousadamarealta.model.Reservation;
 48	import com.pousadamarealta.model.RatePlan;
 49	import com.pousadamarealta.model.Room;
 50	import com.pousadamarealta.repository.RoomRepository;
 51	import com.pousadamarealta.util.Formatter;
 52	import java.math.BigDecimal;
 53	import java.time.LocalDate;
 54	import java.time.format.DateTimeParseException;
 55	import java.util.Map;
 56	
 57	public class ReservationHandler {
 58	    private ReservationService reservationService;
 59	    private RoomRepository roomRepository;
 60	
 61	    public ReservationHandler(Database database) {
 62	        this.reservationService = new ReservationService(database);
 63	        this.roomRepository = new RoomRepository(database);
 64	    }
 65	
 66	    public void createReservation(Context ctx) throws Exception {
 67	        try {
 68	            Map<String, Object> body = ctx.bodyAsClass(Map.class);
 69	
 70	            int roomNumber = getInt(body, "roomNumber");
 71	            String guestName = getString(body, "guestName");
 72	            String guestEmail = getString(body, "guestEmail");
 73	            String guestCpf = getString(body, "guestCpf");
 74	            LocalDate checkIn = parseDate(getString(body, "checkIn"));
 75	            LocalDate checkOut = parseDate(getString(body, "checkOut"));
 76	            int guests = getInt(body, "guests");
 77	            String ratePlanStr = getString(body, "ratePlan");
 78	
 79	            if (roomNumber == 0 || guestName == null || guestEmail == null || guestCpf == null ||
 80	                checkIn == null || checkOut == null || guests == 0 || ratePlanStr == null) {
 81	                ctx.status(400).json(Map.of("error", "INVALID_REQUEST", "message", "Missing required fields"));
 82	                return;
 83	            }
 84	
 85	            if (checkOut.isBefore(checkIn) || checkOut.equals(checkIn)) {
 86	                ctx.status(400).json(Map.of("error", "INVALID_REQUEST", "message", "Invalid date range"));
 87	                return;
 88	            }
 89	
 90	            RatePlan ratePlan = RatePlan.valueOf(ratePlanStr);
 91	            Reservation reservation = reservationService.createReservation(roomNumber, guestName, guestEmail,
 92	                                                                           guestCpf, checkIn, checkOut, guests, ratePlan);
 93	
 94	            ctx.status(201).json(toDto(reservation));
 95	        } catch (ValidationException e) {
 96	            int status = switch (e.getErrorCode()) {
 97	                case "ROOM_NOT_FOUND" -> 404;
 98	                case "CAPACITY_EXCEEDED" -> 422;
 99	                case "ROOM_UNAVAILABLE" -> 409;
100	                default -> 400;
101	            };
102	            ctx.status(status).json(Map.of("error", e.getErrorCode(), "message", e.getMessage()));
103	        } catch (DateTimeParseException e) {
104	            ctx.status(400).json(Map.of("error", "INVALID_REQUEST", "message", "Invalid date format"));
105	        } catch (Exception e) {
106	            handleError(ctx, e);
107	        }
108	    }
109	
110	    public void getReservation(Context ctx) throws Exception {
111	        try {
112	            Long id = Long.parseLong(ctx.pathParam("id"));
113	            Reservation reservation = reservationService.getReservation(id);
114	            ctx.json(toDto(reservation));
115	        } catch (ValidationException e) {
116	            ctx.status(404).json(Map.of("error", e.getErrorCode(), "message", e.getMessage()));
117	        } catch (Exception e) {
118	            handleError(ctx, e);
119	        }
120	    }
121	
122	    public void confirmReservation(Context ctx) throws Exception {
123	        try {
124	            Long id = Long.parseLong(ctx.pathParam("id"));
125	            Map<String, Object> body = ctx.bodyAsClass(Map.class);
126	            BigDecimal amountPaid = new BigDecimal(body.get("amountPaid").toString());
127	
128	            Reservation reservation = reservationService.confirmReservation(id, amountPaid);
129	            ctx.json(toDto(reservation));
130	        } catch (ValidationException e) {
131	            ctx.status(409).json(Map.of("error", e.getErrorCode(), "message", e.getMessage()));
132	        } catch (Exception e) {
133	            handleError(ctx, e);
134	        }
135	    }
136	
137	    public void cancelReservation(Context ctx) throws Exception {
138	        try {
