144	        } catch (Exception e) {
145	            handleError(ctx, e);
146	        }
147	    }
148	
149	    public void checkIn(Context ctx) throws Exception {
150	        try {
151	            Long id = Long.parseLong(ctx.pathParam("id"));
152	            Reservation reservation = reservationService.checkIn(id);
153	            ctx.json(toDto(reservation));
154	        } catch (ValidationException e) {
155	            ctx.status(409).json(Map.of("error", e.getErrorCode(), "message", e.getMessage()));
156	        } catch (Exception e) {
157	            handleError(ctx, e);
158	        }
159	    }
160	
161	    public void checkOut(Context ctx) throws Exception {
162	        try {
163	            Long id = Long.parseLong(ctx.pathParam("id"));
164	            Reservation reservation = reservationService.checkOut(id);
165	            Room room = roomRepository.findByNumber(reservation.getRoomNumber());
166	            String comprovante = reservationService.buildComprovante(reservation, room);
167	
168	            Map<String, Object> response = new java.util.HashMap<>();
169	            response.put("title", "Comprovante de reserva");
170	            response.put("reservationId", reservation.getId());
171	            response.put("guestName", reservation.getGuestName());
172	            response.put("guestCpf", reservation.getGuestCpf());
173	            response.put("roomNumber", reservation.getRoomNumber());
174	            response.put("roomType", room.getType().name());
175	            response.put("checkIn", Formatter.formatIsoDate(reservation.getCheckIn()));
176	            response.put("checkOut", Formatter.formatIsoDate(reservation.getCheckOut()));
177	            response.put("nights", reservation.getNights());
178	            response.put("subtotal", reservation.getSubtotal());
179	            response.put("discount", reservation.getDiscount());
180	            response.put("total", reservation.getTotal());
181	
182	            ctx.json(response);
183	        } catch (ValidationException e) {
184	            ctx.status(409).json(Map.of("error", e.getErrorCode(), "message", e.getMessage()));
185	        } catch (Exception e) {
186	            handleError(ctx, e);
187	        }
188	    }
189	
190	    public void getDocument(Context ctx) throws Exception {
191	        try {
192	            Long id = Long.parseLong(ctx.pathParam("id"));
193	            Reservation reservation = reservationService.getReservation(id);
194	
195	            if (!reservation.getStatus().name().matches("CONFIRMED|CHECKED_IN|CHECKED_OUT")) {
196	                ctx.status(409).json(Map.of("error", "OPERATION_NOT_ALLOWED", "message", "Document not available"));
197	                return;
198	            }
199	
200	            Room room = roomRepository.findByNumber(reservation.getRoomNumber());
201	            String comprovante = reservationService.buildComprovante(reservation, room);
202	
203	            Map<String, Object> response = new java.util.HashMap<>();
204	            response.put("title", "Comprovante de reserva");
205	            response.put("reservationId", reservation.getId());
206	            response.put("guestName", reservation.getGuestName());
207	            response.put("guestCpf", reservation.getGuestCpf());
208	            response.put("roomNumber", reservation.getRoomNumber());
209	            response.put("roomType", room.getType().name());
210	            response.put("checkIn", Formatter.formatIsoDate(reservation.getCheckIn()));
211	            response.put("checkOut", Formatter.formatIsoDate(reservation.getCheckOut()));
212	            response.put("nights", reservation.getNights());
213	            response.put("subtotal", reservation.getSubtotal());
214	            response.put("discount", reservation.getDiscount());
215	            response.put("total", reservation.getTotal());
216	
217	            ctx.json(response);
218	        } catch (ValidationException e) {
219	            ctx.status(404).json(Map.of("error", e.getErrorCode(), "message", e.getMessage()));
220	        } catch (Exception e) {
221	            handleError(ctx, e);
222	        }
223	    }
224	
225	    private ReservationDto toDto(Reservation reservation) {
226	        return new ReservationDto(
227	            reservation.getId(),
228	            reservation.getRoomNumber(),
229	            reservation.getGuestName(),
230	            reservation.getGuestEmail(),
231	            reservation.getGuestCpf(),
232	            Formatter.formatIsoDate(reservation.getCheckIn()),
233	            Formatter.formatIsoDate(reservation.getCheckOut()),
234	            reservation.getGuests(),
235	            reservation.getRatePlan().name(),
236	            reservation.getNights(),
237	            reservation.getSubtotal(),
238	            reservation.getDiscount(),
239	            reservation.getTotal(),
240	            reservation.getStatus().name(),
241	            reservation.getAmountPaid(),
242	            reservation.getRefund()
243	        );
244	    }
245	
246	    private void handleError(Context ctx, Exception e) {
247	        ctx.status(500).json(Map.of("error", "INTERNAL_ERROR", "message", e.getMessage()));
248	    }
249	
250	    private int getInt(Map<String, Object> map, String key) {
251	        Object value = map.get(key);
252	        if (value == null) return 0;
253	        if (value instanceof Integer) return (Integer) value;
254	        if (value instanceof Number) return ((Number) value).intValue();
255	        try {
256	            return Integer.parseInt(value.toString());
257	        } catch (NumberFormatException e) {
258	            return 0;
259	        }
260	    }
261	
262	    private String getString(Map<String, Object> map, String key) {
263	        Object value = map.get(key);
264	        return value != null ? value.toString() : null;
265	    }
266	
267	    private LocalDate parseDate(String dateStr) {
268	        if (dateStr == null || dateStr.isEmpty()) return null;
269	        try {
270	            return LocalDate.parse(dateStr);
271	        } catch (DateTimeParseException e) {
272	            return null;
273	        }
274	    }
275	
276	    public static class ReservationDto {
277	        public Long id;
278	        public int roomNumber;
279	        public String guestName;
280	        public String guestEmail;
281	        public String guestCpf;
282	        public String checkIn;
283	        public String checkOut;
284	        public int guests;
285	        public String ratePlan;
286	        public int nights;
287	        public Object subtotal;
288	        public Object discount;
289	        public Object total;
290	        public String status;
291	        public Object amountPaid;
292	        public Object refund;
293	
294	        public ReservationDto(Long id, int roomNumber, String guestName, String guestEmail,
295	                             String guestCpf, String checkIn, String checkOut, int guests,
296	                             String ratePlan, int nights, Object subtotal, Object discount,
297	                             Object total, String status, Object amountPaid, Object refund) {
298	            this.id = id;
299	            this.roomNumber = roomNumber;
300	            this.guestName = guestName;
301	            this.guestEmail = guestEmail;
302	            this.guestCpf = guestCpf;
303	            this.checkIn = checkIn;
304	            this.checkOut = checkOut;
305	            this.guests = guests;
306	            this.ratePlan = ratePlan;
307	            this.nights = nights;
308	            this.subtotal = subtotal;
309	            this.discount = discount;
310	            this.total = total;
311	            this.status = status;
312	            this.amountPaid = amountPaid;
313	            this.refund = refund;
314	        }
315	    }
316	}

