 28	    public void occupancy(Context ctx) throws Exception {
 29	        try {
 30	            String dateStr = ctx.queryParam("date");
 31	            if (dateStr == null || dateStr.isEmpty()) {
 32	                ctx.status(400).json(Map.of("error", "INVALID_REQUEST", "message", "date parameter is required"));
 33	                return;
 34	            }
 35	
 36	            LocalDate date = LocalDate.parse(dateStr);
