 39	
 40	            csv.append("Pousada Maré Alta,occupancy,").append(Formatter.formatIsoDate(date)).append("\n");
 41	            csv.append("room,type,reservation,check_in,check_out\n");
 42	
 43	            int occupiedCount = 0;
 44	            for (Room room : rooms) {
 45	                List<Reservation> reservations = reservationRepository.findByRoomAndDate(room.getNumber(), date);
 46	                if (!reservations.isEmpty()) {
 47	                    for (Reservation reservation : reservations) {
 48	                        if (isPaidReservation(reservation)) {
 49	                            csv.append(room.getNumber()).append(",");
