121	
122	            BigDecimal tourismTaxRate = new BigDecimal("4.50");
123	            BigDecimal total = BigDecimal.ZERO;
124	
125	            for (Reservation reservation : reservations) {
126	                BigDecimal tax = BigDecimal.valueOf(reservation.getGuests())
