128	                        .multiply(tourismTaxRate);
129	                tax = tax.setScale(2, java.math.RoundingMode.HALF_EVEN);
130	
131	                csv.append(reservation.getId()).append(",");
132	                csv.append(reservation.getRoomNumber()).append(",");
133	                csv.append(Formatter.formatIsoDate(reservation.getCheckIn())).append(",");
134	                csv.append(Formatter.formatIsoDate(reservation.getCheckOut())).append(",");
135	                csv.append(reservation.getGuests()).append(",");
136	                csv.append(reservation.getNights()).append(",");
137	                csv.append(Formatter.formatCsvCurrency(tax)).append("\n");
138	                total = total.add(tax);
139	            }
140	
141	            csv.append("total,,,,,").append(Formatter.formatCsvCurrency(total)).append("\n");
142	
143	            ctx.contentType("text/csv; charset=utf-8").result(csv.toString());
144	        } catch (DateTimeParseException e) {
145	            ctx.status(400).json(Map.of("error", "INVALID_REQUEST", "message", "Invalid month format"));
146	        } catch (Exception e) {
147	            ctx.status(500).json(Map.of("error", "INTERNAL_ERROR", "message", e.getMessage()));
148	        }
149	    }
