151	    public void ratePlans(Context ctx) throws Exception {
152	        try {
153	            String monthStr = ctx.queryParam("month");
154	            if (monthStr == null || monthStr.isEmpty()) {
155	                ctx.status(400).json(Map.of("error", "INVALID_REQUEST", "message", "month parameter is required"));
156	                return;
157	            }
158	
159	            YearMonth yearMonth = YearMonth.parse(monthStr);
160	            List<Reservation> reservations = reservationRepository.findPaidByMonth(yearMonth.getYear(), yearMonth.getMonthValue());
161	
162	            Map<RatePlan, List<Reservation>> grouped = reservations.stream()
163	                    .collect(Collectors.groupingBy(Reservation::getRatePlan));
164	
165	            StringBuilder csv = new StringBuilder();
166	            csv.append("Pousada Maré Alta,rate-plans,").append(monthStr).append("\n");
167	            csv.append("rate_plan,reservations,amount\n");
168	
169	            BigDecimal totalAmount = BigDecimal.ZERO;
170	            int totalReservations = 0;
171	
172	            for (RatePlan plan : new RatePlan[]{RatePlan.STANDARD, RatePlan.NON_REFUNDABLE}) {
173	                List<Reservation> planReservations = grouped.getOrDefault(plan, List.of());
174	                BigDecimal amount = BigDecimal.ZERO;
175	
176	                for (Reservation reservation : planReservations) {
177	                    BigDecimal refund = reservation.getRefund() != null ? reservation.getRefund() : BigDecimal.ZERO;
178	                    amount = amount.add(reservation.getAmountPaid().subtract(refund));
179	                }
180	
181	                csv.append(plan).append(",");
182	                csv.append(planReservations.size()).append(",");
183	                csv.append(Formatter.formatCsvCurrency(amount)).append("\n");
184	
185	                totalAmount = totalAmount.add(amount);
186	                totalReservations += planReservations.size();
187	            }
188	
189	            csv.append("total,").append(totalReservations).append(",").append(Formatter.formatCsvCurrency(totalAmount)).append("\n");
190	
191	            ctx.contentType("text/csv; charset=utf-8").result(csv.toString());
192	        } catch (DateTimeParseException e) {
193	            ctx.status(400).json(Map.of("error", "INVALID_REQUEST", "message", "Invalid month format"));
194	        } catch (Exception e) {
195	            ctx.status(500).json(Map.of("error", "INTERNAL_ERROR", "message", e.getMessage()));
196	        }
197	    }
198	
199	    private boolean isPaidReservation(Reservation reservation) {
200	        String status = reservation.getStatus().name();
201	        return status.equals("CONFIRMED") || status.equals("CHECKED_IN") || status.equals("CHECKED_OUT");
202	    }
203	}
