183	import java.text.DecimalFormat;
184	import java.text.DecimalFormatSymbols;
185	import java.time.LocalDate;
186	import java.time.format.DateTimeFormatter;
187	import java.util.Locale;
188	
189	public class Formatter {
190	    private static final DateTimeFormatter BR_DATE_FORMATTER = DateTimeFormatter.ofPattern("dd/MM/yyyy");
191	    private static final DateTimeFormatter ISO_DATE_FORMATTER = DateTimeFormatter.ofPattern("yyyy-MM-dd");
192	    private static final DecimalFormat CURRENCY_FORMAT;
193	
194	    static {
195	        DecimalFormatSymbols symbols = new DecimalFormatSymbols(Locale.of("pt", "BR"));
196	        symbols.setDecimalSeparator(',');
197	        symbols.setGroupingSeparator('.');
198	        CURRENCY_FORMAT = new DecimalFormat("#,##0.00", symbols);
199	    }
200	
201	    public static String formatBrDate(LocalDate date) {
202	        return date.format(BR_DATE_FORMATTER);
203	    }
204	
205	    public static String formatIsoDate(LocalDate date) {
206	        return date.format(ISO_DATE_FORMATTER);
207	    }
208	
209	    public static String formatCurrency(BigDecimal value) {
210	        return "R$ " + CURRENCY_FORMAT.format(value);
211	    }
212	
213	    public static String formatCsvCurrency(BigDecimal value) {
214	        return String.format("%.2f", value);
215	    }
216	
217	    public static String formatCpf(String cpf) {
218	        if (cpf == null || cpf.length() != 11) {
219	            return cpf;
220	        }
221	        return cpf.substring(0, 3) + "." + cpf.substring(3, 6) + "." +
222	               cpf.substring(6, 9) + "-" + cpf.substring(9);
223	    }
224	}
225	package com.pousadamarealta.util;
226	
227	import com.pousadamarealta.model.RatePlan;
228	import java.math.BigDecimal;
229	import java.math.RoundingMode;
230	import java.time.LocalDate;
231	
232	public class PriceCalculator {
233	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = BigDecimal.valueOf(1.20);
234	    private static final BigDecimal NON_REFUNDABLE_DISCOUNT = BigDecimal.valueOf(0.15);
235	
236	    public static boolean isHighSeason(LocalDate date) {
237	        int month = date.getMonthValue();
238	        int dayOfMonth = date.getDayOfMonth();
239	
240	        if (month == 7) return true;
241	        if (month == 12 && dayOfMonth >= 15) return true;
242	        if (month == 1 || month == 2) return true;
243	
244	        return false;
245	    }
246	
247	    public static BigDecimal calculateNightlyPrice(BigDecimal baseRate, LocalDate date) {
248	        BigDecimal price = baseRate;
249	        if (isHighSeason(date)) {
250	            price = price.multiply(HIGH_SEASON_MULTIPLIER);
251	        }
252	        return roundHalfToEven(price, 2);
253	    }
254	
255	    public static BigDecimal calculateSubtotal(BigDecimal baseRate, LocalDate checkIn, LocalDate checkOut) {
256	        BigDecimal subtotal = BigDecimal.ZERO;
257	        LocalDate current = checkIn;
258	        while (current.isBefore(checkOut)) {
259	            subtotal = subtotal.add(calculateNightlyPrice(baseRate, current));
260	            current = current.plusDays(1);
261	        }
262	        return roundHalfToEven(subtotal, 2);
263	    }
264	
265	    public static BigDecimal calculateDiscount(BigDecimal subtotal, RatePlan ratePlan) {
266	        if (ratePlan == RatePlan.NON_REFUNDABLE) {
267	            return roundHalfToEven(subtotal.multiply(NON_REFUNDABLE_DISCOUNT), 2);
268	        }
269	        return BigDecimal.ZERO;
270	    }
271	
272	    public static BigDecimal calculateTotal(BigDecimal subtotal, BigDecimal discount) {
273	        return roundHalfToEven(subtotal.subtract(discount), 2);
274	    }
275	
276	    public static BigDecimal roundHalfToEven(BigDecimal value, int scale) {
277	        return value.setScale(scale, RoundingMode.HALF_EVEN);
278	    }
279	
280	    public static int countNights(LocalDate checkIn, LocalDate checkOut) {
281	        return (int) java.time.temporal.ChronoUnit.DAYS.between(checkIn, checkOut);
282	    }
283	}

